// Pull the five sources into one flat object. Every source is optional — a
// broken Google token should still produce a Facebook report, not an error.
function safe(nodeName) {
  try {
    const data = $(nodeName).all();
    return data.length ? data[0].json : null;
  } catch {
    return null;
  }
}

const fb = safe('Facebook Insights');
const ig = safe('Instagram Insights');
const gbp = safe('Google Business Performance');
const token = safe('Meta Token Health');
const crm = safe('CRM Post History');

function metaMetrics(payload) {
  const out = {};
  for (const m of payload?.data ?? []) {
    // Page insights return a values[] series; IG total_value returns a scalar.
    if (Array.isArray(m.values) && m.values.length) {
      out[m.name] = m.values.reduce((sum, v) => sum + (typeof v.value === 'number' ? v.value : 0), 0);
    } else if (m.total_value && typeof m.total_value.value === 'number') {
      out[m.name] = m.total_value.value;
    }
  }
  return out;
}

function gbpTotals(payload) {
  const out = {};
  for (const series of payload?.multiDailyMetricTimeSeries ?? []) {
    for (const entry of series.dailyMetricTimeSeries ?? []) {
      const total = (entry.timeSeries?.datedValues ?? []).reduce(
        (sum, d) => sum + Number(d.value ?? 0),
        0,
      );
      out[entry.dailyMetric] = total;
    }
  }
  return out;
}

// --- Token expiry
let tokenDaysLeft = null;
let tokenValid = null;
const tokenData = token?.data;
if (tokenData) {
  tokenValid = tokenData.is_valid === true;
  if (tokenData.expires_at === 0) {
    tokenDaysLeft = Infinity; // System User token — never expires
  } else if (typeof tokenData.expires_at === 'number') {
    tokenDaysLeft = Math.floor((tokenData.expires_at * 1000 - Date.now()) / 86400000);
  }
}

// --- CRM publishing outcomes over the last 7 days
const weekAgo = Date.now() - 7 * 86400000;
const history = (crm && Array.isArray(crm.jobs)) ? crm.jobs : [];

// The queue endpoint returns jobs (post x platform). Count distinct posts by id.
const byPost = new Map();
for (const job of history) {
  if (!byPost.has(job.postId)) byPost.set(job.postId, job);
}

const sources = { facebook: Boolean(fb && !fb.error), instagram: Boolean(ig && !ig.error), google: Boolean(gbp && !gbp.error), crm: Boolean(crm && !crm.error) };

return [{
  json: {
    weekEnding: new Date().toISOString().slice(0, 10),
    sources,
    facebook: metaMetrics(fb),
    instagram: metaMetrics(ig),
    googleBusiness: gbpTotals(gbp),
    token: {
      valid: tokenValid,
      daysLeft: tokenDaysLeft === Infinity ? 'never expires' : tokenDaysLeft,
      needsAttention: tokenValid === false || (typeof tokenDaysLeft === 'number' && tokenDaysLeft < 14),
    },
    scheduled: byPost.size,
    errors: [
      fb?.error && `Facebook: ${fb.error.message}`,
      ig?.error && `Instagram: ${ig.error.message}`,
      gbp?.error && `Google: ${gbp.error.message}`,
      crm?.error && `CRM: ${crm.error}`,
    ].filter(Boolean),
  },
}];

