// Prose from the model, raw numbers appended underneath. If the model call
// failed the email still goes out with the numbers — the report is the data,
// the summary is a convenience.
const data = $('Assemble Numbers').item.json;
const res = $json;

const textBlock = (res.content ?? []).find((b) => b.type === 'text');
const summary = textBlock?.text ?? `(Summary unavailable: ${res.error?.message ?? res.stop_reason ?? 'unknown'}.)`;

function table(title, obj) {
  const rows = Object.entries(obj ?? {});
  if (!rows.length) return `${title}: no data returned.`;
  return `${title}\n` + rows.map(([k, v]) => `  ${k}: ${v}`).join('\n');
}

const body = [
  summary.trim(),
  '',
  '---',
  '',
  table('Facebook', data.facebook),
  '',
  table('Instagram', data.instagram),
  '',
  table('Google Business Profile', data.googleBusiness),
  '',
  `Posts tracked in the CRM: ${data.scheduled}`,
  `Meta token: ${data.token.valid === false ? 'INVALID' : 'valid'}, ${data.token.daysLeft} days left`,
  data.errors.length ? `\nSources that failed this run:\n${data.errors.map((e) => `  - ${e}`).join('\n')}` : '',
].join('\n');

return {
  json: {
    subject: `${data.token.needsAttention ? '[ACTION NEEDED] ' : ''}Diversity Roofing — social week ending ${data.weekEnding}`,
    body,
  },
};
